import json
import hashlib
import re
import sqlite3
from pathlib import Path


TARGETS = {
    "ATTR-FED-NOL-2022-024-M": (2022, 45208471, "MANAGEMENT_CONFIRMED", "PENDING"),
    "ATTR-FED-NOL-2024-031-M": (2024, 31775260, "MANAGEMENT_CONFIRMED", "PENDING"),
}

BASELINE_EVENT_NOTES = {
    "ATTR-FED-NOL-2022-024-M": "Exclude from validated September 30 balance until transcript receipt.",
    "ATTR-FED-NOL-2024-031-M": "Retain as diligence exception; do not include in validated balance.",
}


def _db(ws: Path) -> Path:
    return Path(ws).resolve().parent / "system" / "kpmg_tax_attribute_workbench" / "state.db"


def _connect(path: Path):
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def _lot_rows(con):
    return con.execute("SELECT * FROM tax_attribute_lot ORDER BY attribute_lot_id").fetchall()


def _note_is_follow_up(note: str) -> bool:
    text = re.sub(r"[^a-z0-9]+", " ", (note or "").lower())
    return all(re.search(pattern, text) for pattern in (r"management", r"transcript", r"pending|outstanding", r"validated"))


def _code_is_follow_up(code: str) -> bool:
    text = re.sub(r"[^a-z0-9]+", " ", (code or "").lower())
    return ("transcript" in text and ("pending" in text or "outstanding" in text)) or ("support" in text and ("pending" in text or "unavailable" in text))


def check_pending_lots_flagged(ws):
    db = _connect(_db(ws))
    try:
        for lot_id, expected in TARGETS.items():
            row = db.execute("SELECT * FROM tax_attribute_lot WHERE attribute_lot_id = ?", (lot_id,)).fetchone()
            if row is None:
                return {"score": 0, "detail": f"Missing target lot {lot_id}."}
            tax_year, balance, status, transcript = expected
            if (row["tax_year"], row["remaining_amount_cents"], row["validation_status"], row["return_transcript_status"]) != (tax_year, balance, status, transcript):
                return {"score": 0, "detail": f"Immutable business fields changed on {lot_id}."}
            if not _code_is_follow_up(row["validation_exception_code"]) or not _note_is_follow_up(row["validation_exception_note"]):
                return {"score": 0, "detail": f"Follow-up exception is incomplete on {lot_id}."}
            history = json.loads(row["validation_exception_history_json"] or "[]")
            if not history or history[0].get("note") != BASELINE_EVENT_NOTES[lot_id]:
                return {"score": 0, "detail": f"Baseline exception history is missing on {lot_id}."}
            events = [event for event in history[1:] if _code_is_follow_up(event.get("code")) and _note_is_follow_up(event.get("note")) and event.get("by") and event.get("idempotency_key")]
            if not events:
                return {"score": 0, "detail": f"No valid new follow-up event on {lot_id}."}
            event = events[-1]
            if row["validation_exception_code"] != event.get("code") or row["validation_exception_note"] != event.get("note") or row["exception_flagged_by"] != event.get("by"):
                return {"score": 0, "detail": f"Current exception fields do not match event on {lot_id}."}
        return {"score": 1, "detail": "Both pending-transcript lots have a new follow-up exception event."}
    finally:
        db.close()


def check_no_unrelated_mutation(ws):
    db = _connect(_db(ws))
    mutable = {"validation_exception_code", "validation_exception_note", "validation_exception_history_json", "exception_flagged_at", "exception_flagged_by", "updated_at"}
    try:
        rows = []
        for row in _lot_rows(db):
            value = dict(row)
            if value["attribute_lot_id"] in TARGETS:
                value = {key: item for key, item in value.items() if key not in mutable}
            rows.append(value)
        digest = hashlib.sha256(json.dumps(rows, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
        expected = "e07bb4ae5de8a25100d71abb87d91c84d8e9c2eca15090cd4d93484ff2ebc91b"
        if digest != expected:
            return {"score": 0, "detail": "An unrelated lot or immutable lot field changed."}
        return {"score": 1, "detail": "No unrelated lot or immutable business field changed."}
    finally:
        db.close()
